  inputOnly      MFNode   on_VSPH_g
  inputOutput    MFNode   VSPH_g [ ]
  inputOutput    SFInt32  VSPH_g_count 5
  inputOutput    SFString log "VBND_a1 VBND_g1 VALL_a1 VALL_g1 VSA_a1 VSA_g1 VSPH_a1 VSPH_g1 Kb VALL_g2 VSA_a0 VSA_g0 VBND_g2 VSPH_g1 VBND_g1 VALL_g1 Kl VALL_a0 VALL_g0 VBND_g2 VSA_a1 VSA_g1 VBND_g1 VSPH_g1 Kr VALL_a1 VALL_g1 Ke VBND_g2 VALL_a0 VALL_g0 VSA_a0 VSA_g0 VALL_a1 VALL_g1 VSA_a1 VSA_g1 VBND_g1 Kc VALL_g2 VSA_g2 VBND_g2 VALL_g1 VSA_g1 Kg VBND_g1 VALL_a0 VALL_g0 VSA_a0 VSA_g0 Kf VSPH_g1 VBND_g1 VALL_a1 VALL_g1 VSA_a1 VSA_g1 Kt VALL_a0 VALL_g0 VSA_a0 VSA_g0 VBND_a0 VBND_g0 VSPH_a0 VSPH_g0 "
